{ "id": "o_42", "total": 4000 }
// after deploy: every client reading `total` breaks
{ "id": "o_42", "amountCents": 4000 }

good.code:
// step 1: add the new field, keep the old one
{ "id": "o_42", "total": 4000, "amountCents": 4000 }
// step 2: docs + Deprecation on `total`, track readers
// step 3: remove `total` only in the next major version

better.code:
type Order = { id: string; amountCents: number }
function parseOrder(raw: unknown): Order {
  const o = raw as Record<string, unknown>
  // read only what we need; ignore anything new
  return { id: String(o.id), amountCents: Number(o.amountCents) }
}
